raw_args.content:
import csv
qid_counts = {}
with open('outputs/t09_poi_nearest_stop.csv', mode='r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        qid = row['qid']
        qid_counts[qid] = qid_counts.get(qid, 0) + 1

for qid, count in qid_counts.items():
    if count > 1:
        print(f"qid {qid} appears {count} times")
